4	import { createClient, createAdminClient } from '@/lib/supabase/server';
5	import { revalidatePath } from 'next/cache';
6	import { z } from 'zod';
7	import { ensureGenerationRoleExists } from './generations';
8	
9	const studentNumberRegex = /^[0-9]+$/;
10	
11	// Schema for re-syncing Discord member (for users who left and rejoined)
12	const reSyncSchema = z.object({
13	    last_name: z.string().min(1, '姓は必須です。'),
14	    first_name: z.string().min(1, '名は必須です。'),
15	});
16	
17	// Schema for updating own profile (allows changing student number)
18	const profileUpdateSchema = z.object({
19	    student_number: z.string().regex(/^[0-9]*$/, '学籍番号は半角数字で入力してください。').optional().nullable(),
20	});
21	
22	
23	// Schema for admin updating profile
24	const profileAdminUpdateSchema = z.object({
25	    last_name: z.string().min(1, '姓は必須です。'),
26	    first_name: z.string().min(1, '名は必須です。'),
27	    generation: z.coerce.number().int().min(0, '期は0以上の数字である必要があります。'),
28	    student_number: z.string().optional().nullable(),
29	    status: z.coerce.number().int().min(0).max(2),
30	    team_ids: z.array(z.string()).optional(),
31	});
32	
33	// Schema for initial registration
34	const registerSchema = z.object({
35	    last_name: z.string().min(1, '姓は必須です。'),
36	    first_name: z.string().min(1, '名は必須です。'),
37	    status: z.coerce.number().int().min(0).max(2),
38	    grade: z.coerce.number().int().min(1).max(3).optional(),
39	    student_number: z.string().regex(studentNumberRegex, '学籍番号は半角数字で入力してください。').optional().nullable(),
40	    generation: z.coerce.number().int().min(1, '期は正の整数である必要があります。').optional(),
41	    team_ids: z.array(z.string()).optional(),
42	}).refine(data => {
43	    if (data.status === 0 || data.status === 1) {
44	        return !!data.grade;
45	    }
46	    return true;
47	}, {
48	    message: '学年は必須です。',
49	    path: ['grade'],
50	}).refine(data => {
51	    if (data.status === 2) { // OB/OG
52	        return !!data.generation;
53	    }
54	    return true;
55	}, {
56	    message: '期は必須です。',
57	    path: ['generation'],
58	});
59	
60	async function checkAdmin() {
61	    const supabase = await createClient();
62	    const { data: { user } } = await supabase.auth.getUser();
63	    if (!user) throw new Error('Authentication required.');
64	
65	    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
66	    if (!admin?.is_admin) throw new Error('Administrator privileges required.');
67	}
68	
69	function getAcademicYear() {
70	    const today = new Date();
71	    const year = today.getFullYear();
72	    const month = today.getMonth(); // 0-indexed (0 for January)
73	    return month >= 3 ? year : year - 1; // Academic year starts in April (month 3)
74	}
75	
76	function calculateGeneration(status: number, grade: number, academicYear: number) {
77	    if (status === 1) { // High School
78	        return 10 + (academicYear - 2025) - grade + 1;
79	    }
80	    if (status === 0) { // Junior High
81	        return 10 + (academicYear - 2025) + 4 - grade;
82	    }
83	    return null;
84	}
