149	export async function getMemberDisplayName(discordUid: string): Promise<string | null> {
150	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
151	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
152	
153	    if (!apiUrl || !token || !discordUid) {
154	        console.error(`[Discord Bot] Cannot get display name. API URL, Token, or Discord UID is missing.`);
155	        return null;
156	    }
157	
158	    try {
159	        const response = await fetch(`${apiUrl}/api/nickname?discord_uid=${discordUid}`, {
160	            headers: {
161	                'Authorization': `Bearer ${token}`,
162	            },
163	            cache: 'no-store',
164	        });
165	
166	        if (!response.ok) {
167	            const errorText = await response.text();
168	            console.error(`[Discord Bot] Failed to fetch nickname for ${discordUid}: Status ${response.status}, Body: ${errorText}`);
169	            return null;
170	        }
171	        
172	        const data = await response.json();
173	        return data.name_only || null;
174	    } catch (error) {
175	        console.error(`[Discord Bot] Error fetching nickname for ${discordUid}:`, error);
176	        return null;
177	    }
178	}
