180	type MemberNameMap = { [key: string]: string };
181	
182	export async function getAllMemberNames(): Promise<MemberNameMap | null> {
183	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
184	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
185	
186	    if (!apiUrl || !token) {
187	        console.error(`[getAllMemberNames] Aborting: API URL or Token is missing.`);
188	        return null;
189	    }
190	
191	    try {
192	        const response = await fetch(`${apiUrl}/api/members`, {
193	            headers: {
194	                'Authorization': `Bearer ${token}`,
195	            },
196	            cache: 'no-store',
197	        });
198	        
199	        if (!response.ok) {
200	            const responseText = await response.text();
201	            console.error(`[getAllMemberNames] Failed to fetch - Status: ${response.status}, Body: ${responseText}`);
202	            return null;
203	        }
204	        
205	        const data = await response.json();
206	        if (!data.success || !Array.isArray(data.data)) {
207	            console.error(`[getAllMemberNames] API response was not successful or data is not an array.`);
208	            return null;
209	        }
210	
211	        const nameMap: MemberNameMap = data.data.reduce((acc: MemberNameMap, member: { uid: string, name: string }) => {
212	            acc[member.uid] = member.name;
213	            return acc;
214	        }, {});
215	        
216	        return nameMap;
217	    } catch (error) {
218	        console.error(`[getAllMemberNames] Error fetching member names:`, error);
219	        return null;
220	    }
221	}
