225	export async function registerNewMember(values: z.infer<typeof registerSchema>) {
226	    const supabase = await createClient();
227	    const supabaseAdmin = await createAdminClient();
228	    const { data: { user } } = await supabase.auth.getUser();
229	
230	    if (!user) {
231	        return { error: '登録するにはログインする必要があります。' };
232	    }
233	    
234	    const { data: existingMember } = await supabase
235	        .from('members')
236	        .select('supabase_auth_user_id')
237	        .eq('supabase_auth_user_id', user.id)
238	        .is('deleted_at', null)
239	        .single();
240	
241	    if (existingMember) {
242	        return { error: 'このユーザーは既に登録済みです。' };
243	    }
244	
245	    const parsedData = registerSchema.safeParse(values);
246	    if (!parsedData.success) {
247	        console.error("Invalid registration data:", parsedData.error.flatten());
248	        const firstError = parsedData.error.flatten().fieldErrors;
249	        const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
250	        return { error: errorMessage };
251	    }
252	    
253	    const { status, last_name, first_name, grade, student_number, generation: directGeneration, team_ids } = parsedData.data;
254	
255	    let finalGeneration: number | null = null;
256	
257	    if (status === 2) { // OB/OG
258	        finalGeneration = directGeneration!;
259	    } else { // Student
260	        const academicYear = getAcademicYear();
261	        finalGeneration = calculateGeneration(status, grade!, academicYear);
262	    }
263	    
264	    if (finalGeneration === null) {
265	        return { error: '期を計算できませんでした。入力内容を確認してください。' };
266	    }
267	
268	    const fullName = (last_name + first_name).replace(/\s/g, '');
269	    
270	    await ensureGenerationRoleExists(finalGeneration);
271	
272	    const discordUsername = user.user_metadata.full_name || null;
273	
274	    const { error: memberInsertError, data: newMember } = await supabase.from('members').insert({
275	        supabase_auth_user_id: user.id,
276	        discord_uid: user.user_metadata.provider_id,
277	        discord_username: discordUsername,
278	        avatar_url: user.user_metadata.avatar_url,
279	        is_admin: false,
280	        status,
281	        student_number,
282	        generation: finalGeneration
283	    }).select().single();
284	
285	    if (memberInsertError) {
286	        console.error('Error creating member profile:', memberInsertError);
287	        return { error: '部員情報の作成に失敗しました。' };
288	    }
289	
290	    // Update user_metadata with name
291	    const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
292	        user.id,
293	        { user_metadata: { ...user.user_metadata, last_name, first_name, name: fullName } }
294	    );
295	     if (userUpdateError) {
296	        console.error('Error updating user metadata:', userUpdateError);
297	        // We don't return an error here, as the primary registration was successful
298	    }
299	    
300	    if (team_ids && team_ids.length > 0) {
301	        const relations = team_ids.map(team_id => ({
302	            member_id: newMember.supabase_auth_user_id,
303	            team_id: team_id
304	        }));
305	        const { error: relationError } = await supabase.from('member_team_relations').insert(relations);
306	        if (relationError) {
307	            console.error('Error creating member-team relations:', relationError);
308	        }
309	    }
310	
311	    await syncDiscordNickname(user.user_metadata.provider_id, fullName);
312	    await syncDiscordRoles(user.user_metadata.provider_id);
313	
314	    revalidatePath('/dashboard', 'layout');
315	    revalidatePath('/dashboard/admin/members');
316	    return { error: null };
317	}
