320	export async function resyncDiscordMember(values: z.infer<typeof reSyncSchema>) {
321	    const supabase = await createClient();
322	    const supabaseAdmin = await createAdminClient();
323	    const { data: { user } } = await supabase.auth.getUser();
324	
325	    if (!user) {
326	        return { error: '再連携するにはログインする必要があります。' };
327	    }
328	
329	    const parsedData = reSyncSchema.safeParse(values);
330	    if (!parsedData.success) {
331	        const firstError = parsedData.error.flatten().fieldErrors;
332	        const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
333	        return { error: errorMessage };
334	    }
335	
336	    const { last_name, first_name } = parsedData.data;
337	    const fullName = (last_name + first_name).replace(/\s/g, '');
338	    const discordUid = user.user_metadata.provider_id;
339	
340	    if (!discordUid) {
341	        return { error: 'Discord UIDが取得できませんでした。' };
342	    }
343	
344	    // Check if member profile exists
345	    const { data: memberProfile } = await supabase
346	        .from('members')
347	        .select('*')
348	        .eq('supabase_auth_user_id', user.id)
349	        .is('deleted_at', null)
350	        .single();
351	
352	    if (!memberProfile) {
353	        return { error: 'メンバー情報が見つかりません。新規登録が必要です。' };
354	    }
355	    
356	    // Update user_metadata with name
357	    const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
358	        user.id,
359	        { user_metadata: { ...user.user_metadata, last_name, first_name, name: fullName } }
360	    );
361	     if (userUpdateError) {
362	        console.error('Error updating user metadata during resync:', userUpdateError);
363	        return { error: 'ユーザー情報の更新に失敗しました。' };
364	    }
365	
366	    // Re-sync Discord nickname and roles
367	    await syncDiscordNickname(discordUid, fullName);
368	    await syncDiscordRoles(discordUid);
369	
370	    revalidatePath('/dashboard', 'layout');
371	    return { error: null };
372	}
