375	export async function updateMyProfile(values: z.infer<typeof profileUpdateSchema>) {
376	    const supabase = await createClient();
377	    const supabaseAdmin = await createAdminClient();
378	    const { data: { user } } = await supabase.auth.getUser();
379	
380	    if (!user) {
381	        return { error: 'プロフィールを更新するにはログインする必要があります。' };
382	    }
383	
384	    const parsedData = profileUpdateSchema.safeParse(values);
385	    if (!parsedData.success) {
386	        return { error: '無効なデータが提供されました。' };
387	    }
388	
389	    const { student_number } = parsedData.data;
390	
391	    const { error } = await supabaseAdmin
392	        .from('members')
393	        .update({ student_number })
394	        .eq('supabase_auth_user_id', user.id);
395	
396	    if (error) {
397	        console.error('Error updating profile:', error);
398	        return { error: 'プロフィールの更新に失敗しました。もう一度お試しください。' };
399	    }
400	
401	    const { data: member } = await supabase.from("members").select("discord_uid").eq("supabase_auth_user_id", user.id).single();
402	    if (member) {
403	        const realName = await getMemberDisplayName(member.discord_uid);
404	        if (realName) await syncDiscordNickname(member.discord_uid, realName);
405	        await syncDiscordRoles(member.discord_uid);
406	    }
407	
408	    revalidatePath('/dashboard', 'layout');
409	    revalidatePath('/dashboard/admin/members');
410	    return { error: null };
411	}
