413	export async function updateMemberAdmin(userId: string, values: z.infer<typeof profileAdminUpdateSchema>) {
414	    try {
415	        await checkAdmin();
416	        const supabase = await createClient();
417	        const supabaseAdmin = await createAdminClient();
418	
419	        const parsedData = profileAdminUpdateSchema.safeParse(values);
420	        if (!parsedData.success) {
421	            console.error("Invalid admin update data:", parsedData.error.flatten());
422	            const firstError = parsedData.error.flatten().fieldErrors;
423	            const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
424	            return { error: errorMessage };
425	        }
426	
427	        const { last_name, first_name, generation, student_number, status, team_ids } = parsedData.data;
428	
429	        // 1. Update user metadata (name)
430	        const fullName = (last_name + first_name).replace(/\s/g, '');
431	        const { data: userToUpdate, error: getUserError } = await supabaseAdmin.auth.admin.getUserById(userId);
432	        if (getUserError) throw new Error(`ユーザー情報の取得に失敗: ${getUserError.message}`);
433	
434	        const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
435	            userId,
436	            { user_metadata: { ...userToUpdate.user.user_metadata, last_name, first_name, name: fullName } }
437	        );
438	        if (userUpdateError) throw new Error(`ユーザーメタデータの更新に失敗: ${userUpdateError.message}`);
439	
440	        // 2. Update member table (generation, status, student_number)
441	        await ensureGenerationRoleExists(generation);
442	        const { error: memberUpdateError } = await supabase
443	            .from('members')
444	            .update({ generation, student_number, status })
445	            .eq('supabase_auth_user_id', userId);
446	        if (memberUpdateError) throw new Error(`メンバーテーブルの更新に失敗: ${memberUpdateError.message}`);
447	        
448	        // 3. Update team relations
449	        const { error: deleteTeamsError } = await supabase
450	            .from('member_team_relations')
451	            .delete()
452	            .eq('member_id', userId);
453	        if (deleteTeamsError) throw new Error(`所属班の削除に失敗: ${deleteTeamsError.message}`);
454	
455	        if (team_ids && team_ids.length > 0) {
456	            const newRelations = team_ids.map(team_id => ({
457	                member_id: userId,
458	                team_id: team_id,
459	            }));
460	            const { error: insertTeamsError } = await supabase.from('member_team_relations').insert(newRelations);
461	            if (insertTeamsError) throw new Error(`所属班の更新に失敗: ${insertTeamsError.message}`);
462	        }
463	
464	        // 4. Sync with Discord
465	        await syncDiscordNickname(userToUpdate.user.user_metadata.provider_id, fullName);
466	        await syncDiscordRoles(userToUpdate.user.user_metadata.provider_id);
467	
468	        revalidatePath('/dashboard/admin/members');
469	        return { error: null };
470	    } catch (e: any) {
471	        console.error('Error updating member by admin:', e);
472	        return { error: e.message };
473	    }
474	}
