477	export async function toggleAdminStatus(userId: string, currentStatus: boolean) {
478	    const supabase = await createClient();
479	    const { data: { user } } = await supabase.auth.getUser();
480	
481	    if (!user) {
482	        return { error: '認証が必要です。' };
483	    }
484	
485	    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
486	    if (!admin?.is_admin) {
487	        return { error: '管理者権限が必要です。' };
488	    }
489	
490	     if (user.id === userId) {
491	        return { error: "自身の管理者ステータスは変更できません。" };
