507	export async function deleteMember(userId: string) {
508	    const supabase = await createClient();
509	    const { data: { user } } = await supabase.auth.getUser();
510	
511	    if (!user) {
512	        return { error: '認証が必要です。' };
513	    }
514	
515	    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
516	    if (!admin?.is_admin) {
517	        return { error: '管理者権限が必要です。' };
518	    }
519	
520	    if (user.id === userId) {
521	        return { error: "自分自身を削除することはできません。" };
522	    }
523	
524	    const { error } = await supabase
525	        .from('members')
526	        .update({ deleted_at: new Date().toISOString() })
527	        .eq('supabase_auth_user_id', userId);
528	
