"use server";

import { createClient, createAdminClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';
import { z } from 'zod';
import { ensureGenerationRoleExists } from './generations';

const studentNumberRegex = /^[0-9]+$/;

// Schema for re-syncing Discord member (for users who left and rejoined)
const reSyncSchema = z.object({
    last_name: z.string().min(1, '姓は必須です。'),
    first_name: z.string().min(1, '名は必須です。'),
});

// Schema for updating own profile (allows changing student number)
const profileUpdateSchema = z.object({
    student_number: z.string().regex(/^[0-9]*$/, '学籍番号は半角数字で入力してください。').optional().nullable(),
});


// Schema for admin updating profile
const profileAdminUpdateSchema = z.object({
    last_name: z.string().min(1, '姓は必須です。'),
    first_name: z.string().min(1, '名は必須です。'),
    generation: z.coerce.number().int().min(0, '期は0以上の数字である必要があります。'),
    student_number: z.string().optional().nullable(),
    status: z.coerce.number().int().min(0).max(2),
    team_ids: z.array(z.string()).optional(),
});

// Schema for initial registration
const registerSchema = z.object({
    last_name: z.string().min(1, '姓は必須です。'),
    first_name: z.string().min(1, '名は必須です。'),
    status: z.coerce.number().int().min(0).max(2),
    grade: z.coerce.number().int().min(1).max(3).optional(),
    student_number: z.string().regex(studentNumberRegex, '学籍番号は半角数字で入力してください。').optional().nullable(),
    generation: z.coerce.number().int().min(1, '期は正の整数である必要があります。').optional(),
    team_ids: z.array(z.string()).optional(),
}).refine(data => {
    if (data.status === 0 || data.status === 1) {
        return !!data.grade;
    }
    return true;
}, {
    message: '学年は必須です。',
    path: ['grade'],
}).refine(data => {
    if (data.status === 2) { // OB/OG
        return !!data.generation;
    }
    return true;
}, {
    message: '期は必須です。',
    path: ['generation'],
});

async function checkAdmin() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error('Authentication required.');

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) throw new Error('Administrator privileges required.');
}

function getAcademicYear() {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth(); // 0-indexed (0 for January)
    return month >= 3 ? year : year - 1; // Academic year starts in April (month 3)
}

function calculateGeneration(status: number, grade: number, academicYear: number) {
    if (status === 1) { // High School
        return 10 + (academicYear - 2025) - grade + 1;
    }
    if (status === 0) { // Junior High
        return 10 + (academicYear - 2025) + 4 - grade;
    }
    return null;
}

async function syncDiscordRoles(discordUid: string) {
    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
    const token = process.env.STEM_BOT_API_BEARER_TOKEN;

    console.log(`[Discord Bot] Attempting to sync roles for discord_uid: ${discordUid}`);

    if (!apiUrl || !token) {
        console.error('[Discord Bot] API URL or Bearer Token is not configured for Discord role sync.');
        return; // Don't throw error, just log and skip sync
    }

    try {
        const res = await fetch(`${apiUrl}/api/roles/sync`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ discord_uid: discordUid }),
            cache: 'no-store',
        });
         if (!res.ok) {
            const errorText = await res.text();
            console.error(`[Discord Bot] Failed to sync roles for ${discordUid}. Status: ${res.status}, Body: ${errorText}`);
        } else {
            console.log(`[Discord Bot] Successfully initiated role sync for discord_uid: ${discordUid}`);
        }
    } catch (e) {
        console.error(`[Discord Bot] Error during role sync for ${discordUid}:`, e);
    }
}

async function syncDiscordNickname(discordUid: string, name: string) {
    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
    const token = process.env.STEM_BOT_API_BEARER_TOKEN;

    console.log(`[Discord Bot] Attempting to update nickname for discord_uid: ${discordUid} to a name based on: "${name}"`);

    if (!apiUrl || !token) {
        console.error('[Discord Bot] API URL or Bearer Token is not configured for Discord nickname sync.');
        return;
    }

    const body = {
        discord_uid: discordUid,
        name: name,
    };

    try {
        const res = await fetch(`${apiUrl}/api/nickname/update`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            body: JSON.stringify(body),
            cache: 'no-store',
        });
        if (!res.ok) {
            const errorBody = await res.text();
            console.error(`[Discord Bot] Failed to update nickname for ${discordUid}. Status: ${res.status}, Body: ${errorBody}`);
        } else {
             console.log(`[Discord Bot] Successfully initiated nickname update for discord_uid: ${discordUid}`);
        }
    } catch(e) {
        console.error(`[Discord Bot] Error during nickname update for ${discordUid}:`, e);
    }
}

export async function getMemberDisplayName(discordUid: string): Promise<string | null> {
    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
    const token = process.env.STEM_BOT_API_BEARER_TOKEN;

    if (!apiUrl || !token || !discordUid) {
        console.error(`[Discord Bot] Cannot get display name. API URL, Token, or Discord UID is missing.`);
        return null;
    }

    try {
        const response = await fetch(`${apiUrl}/api/nickname?discord_uid=${discordUid}`, {
            headers: {
                'Authorization': `Bearer ${token}`,
            },
            cache: 'no-store',
        });

        if (!response.ok) {
            const errorText = await response.text();
            console.error(`[Discord Bot] Failed to fetch nickname for ${discordUid}: Status ${response.status}, Body: ${errorText}`);
            return null;
        }

        const data = await response.json();
        return data.name_only || null;
    } catch (error) {
        console.error(`[Discord Bot] Error fetching nickname for ${discordUid}:`, error);
        return null;
    }
}

type MemberNameMap = { [key: string]: string };

export async function getAllMemberNames(): Promise<MemberNameMap | null> {
    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
    const token = process.env.STEM_BOT_API_BEARER_TOKEN;

    if (!apiUrl || !token) {
        console.error(`[getAllMemberNames] Aborting: API URL or Token is missing.`);
        return null;
    }

    try {
        const response = await fetch(`${apiUrl}/api/members`, {
            headers: {
                'Authorization': `Bearer ${token}`,
            },
            cache: 'no-store',
        });

        if (!response.ok) {
            const responseText = await response.text();
            console.error(`[getAllMemberNames] Failed to fetch - Status: ${response.status}, Body: ${responseText}`);
            return null;
        }

        const data = await response.json();
        if (!data.success || !Array.isArray(data.data)) {
            console.error(`[getAllMemberNames] API response was not successful or data is not an array.`);
            return null;
        }

        const nameMap: MemberNameMap = data.data.reduce((acc: MemberNameMap, member: { uid: string, name: string }) => {
            acc[member.uid] = member.name;
            return acc;
        }, {});

        return nameMap;
    } catch (error) {
        console.error(`[getAllMemberNames] Error fetching member names:`, error);
        return null;
    }
}



export async function registerNewMember(values: z.infer<typeof registerSchema>) {
    const supabase = await createClient();
    const supabaseAdmin = await createAdminClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { error: '登録するにはログインする必要があります。' };
    }

    const { data: existingMember } = await supabase
        .from('members')
        .select('supabase_auth_user_id')
        .eq('supabase_auth_user_id', user.id)
        .is('deleted_at', null)
        .single();

    if (existingMember) {
        return { error: 'このユーザーは既に登録済みです。' };
    }

    const parsedData = registerSchema.safeParse(values);
    if (!parsedData.success) {
        console.error("Invalid registration data:", parsedData.error.flatten());
        const firstError = parsedData.error.flatten().fieldErrors;
        const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
        return { error: errorMessage };
    }

    const { status, last_name, first_name, grade, student_number, generation: directGeneration, team_ids } = parsedData.data;

    let finalGeneration: number | null = null;

    if (status === 2) { // OB/OG
        finalGeneration = directGeneration!;
    } else { // Student
        const academicYear = getAcademicYear();
        finalGeneration = calculateGeneration(status, grade!, academicYear);
    }

    if (finalGeneration === null) {
        return { error: '期を計算できませんでした。入力内容を確認してください。' };
    }

    const fullName = (last_name + first_name).replace(/\s/g, '');

    await ensureGenerationRoleExists(finalGeneration);

    const discordUsername = user.user_metadata.full_name || null;

    const { error: memberInsertError, data: newMember } = await supabase.from('members').insert({
        supabase_auth_user_id: user.id,
        discord_uid: user.user_metadata.provider_id,
        discord_username: discordUsername,
        avatar_url: user.user_metadata.avatar_url,
        is_admin: false,
        status,
        student_number,
        generation: finalGeneration
    }).select().single();

    if (memberInsertError) {
        console.error('Error creating member profile:', memberInsertError);
        return { error: '部員情報の作成に失敗しました。' };
    }

    // Update user_metadata with name
    const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
        user.id,
        { user_metadata: { ...user.user_metadata, last_name, first_name, name: fullName } }
    );
     if (userUpdateError) {
        console.error('Error updating user metadata:', userUpdateError);
        // We don't return an error here, as the primary registration was successful
    }

    if (team_ids && team_ids.length > 0) {
        const relations = team_ids.map(team_id => ({
            member_id: newMember.supabase_auth_user_id,
            team_id: team_id
        }));
        const { error: relationError } = await supabase.from('member_team_relations').insert(relations);
        if (relationError) {
            console.error('Error creating member-team relations:', relationError);
        }
    }

    await syncDiscordNickname(user.user_metadata.provider_id, fullName);
    await syncDiscordRoles(user.user_metadata.provider_id);

    revalidatePath('/dashboard', 'layout');
    revalidatePath('/dashboard/admin/members');
    return { error: null };
}


export async function resyncDiscordMember(values: z.infer<typeof reSyncSchema>) {
    const supabase = await createClient();
    const supabaseAdmin = await createAdminClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { error: '再連携するにはログインする必要があります。' };
    }

    const parsedData = reSyncSchema.safeParse(values);
    if (!parsedData.success) {
        const firstError = parsedData.error.flatten().fieldErrors;
        const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
        return { error: errorMessage };
    }

    const { last_name, first_name } = parsedData.data;
    const fullName = (last_name + first_name).replace(/\s/g, '');
    const discordUid = user.user_metadata.provider_id;

    if (!discordUid) {
        return { error: 'Discord UIDが取得できませんでした。' };
    }

    // Check if member profile exists
    const { data: memberProfile } = await supabase
        .from('members')
        .select('*')
        .eq('supabase_auth_user_id', user.id)
        .is('deleted_at', null)
        .single();

    if (!memberProfile) {
        return { error: 'メンバー情報が見つかりません。新規登録が必要です。' };
    }

    // Update user_metadata with name
    const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
        user.id,
        { user_metadata: { ...user.user_metadata, last_name, first_name, name: fullName } }
    );
     if (userUpdateError) {
        console.error('Error updating user metadata during resync:', userUpdateError);
        return { error: 'ユーザー情報の更新に失敗しました。' };
    }

    // Re-sync Discord nickname and roles
    await syncDiscordNickname(discordUid, fullName);
    await syncDiscordRoles(discordUid);

    revalidatePath('/dashboard', 'layout');
    return { error: null };
}


export async function updateMyProfile(values: z.infer<typeof profileUpdateSchema>) {
    const supabase = await createClient();
    const supabaseAdmin = await createAdminClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { error: 'プロフィールを更新するにはログインする必要があります。' };
    }

    const parsedData = profileUpdateSchema.safeParse(values);
    if (!parsedData.success) {
        return { error: '無効なデータが提供されました。' };
    }

    const { student_number } = parsedData.data;

    const { error } = await supabaseAdmin
        .from('members')
        .update({ student_number })
        .eq('supabase_auth_user_id', user.id);

    if (error) {
        console.error('Error updating profile:', error);
        return { error: 'プロフィールの更新に失敗しました。もう一度お試しください。' };
    }

    const { data: member } = await supabase.from("members").select("discord_uid").eq("supabase_auth_user_id", user.id).single();
    if (member) {
        const realName = await getMemberDisplayName(member.discord_uid);
        if (realName) await syncDiscordNickname(member.discord_uid, realName);
        await syncDiscordRoles(member.discord_uid);
    }

    revalidatePath('/dashboard', 'layout');
    revalidatePath('/dashboard/admin/members');
    return { error: null };
}

export async function updateMemberAdmin(userId: string, values: z.infer<typeof profileAdminUpdateSchema>) {
    try {
        await checkAdmin();
        const supabase = await createClient();
        const supabaseAdmin = await createAdminClient();

        const parsedData = profileAdminUpdateSchema.safeParse(values);
        if (!parsedData.success) {
            console.error("Invalid admin update data:", parsedData.error.flatten());
            const firstError = parsedData.error.flatten().fieldErrors;
            const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
            return { error: errorMessage };
        }

        const { last_name, first_name, generation, student_number, status, team_ids } = parsedData.data;

        // 1. Update user metadata (name)
        const fullName = (last_name + first_name).replace(/\s/g, '');
        const { data: userToUpdate, error: getUserError } = await supabaseAdmin.auth.admin.getUserById(userId);
        if (getUserError) throw new Error(`ユーザー情報の取得に失敗: ${getUserError.message}`);

        const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
            userId,
            { user_metadata: { ...userToUpdate.user.user_metadata, last_name, first_name, name: fullName } }
        );
        if (userUpdateError) throw new Error(`ユーザーメタデータの更新に失敗: ${userUpdateError.message}`);

        // 2. Update member table (generation, status, student_number)
        await ensureGenerationRoleExists(generation);
        const { error: memberUpdateError } = await supabase
            .from('members')
            .update({ generation, student_number, status })
            .eq('supabase_auth_user_id', userId);
        if (memberUpdateError) throw new Error(`メンバーテーブルの更新に失敗: ${memberUpdateError.message}`);

        // 3. Update team relations
        const { error: deleteTeamsError } = await supabase
            .from('member_team_relations')
            .delete()
            .eq('member_id', userId);
        if (deleteTeamsError) throw new Error(`所属班の削除に失敗: ${deleteTeamsError.message}`);

        if (team_ids && team_ids.length > 0) {
            const newRelations = team_ids.map(team_id => ({
                member_id: userId,
                team_id: team_id,
            }));
            const { error: insertTeamsError } = await supabase.from('member_team_relations').insert(newRelations);
            if (insertTeamsError) throw new Error(`所属班の更新に失敗: ${insertTeamsError.message}`);
        }

        // 4. Sync with Discord
        await syncDiscordNickname(userToUpdate.user.user_metadata.provider_id, fullName);
        await syncDiscordRoles(userToUpdate.user.user_metadata.provider_id);

        revalidatePath('/dashboard/admin/members');
        return { error: null };
    } catch (e: any) {
        console.error('Error updating member by admin:', e);
        return { error: e.message };
    }
}


export async function toggleAdminStatus(userId: string, currentStatus: boolean) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { error: '認証が必要です。' };
    }

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) {
        return { error: '管理者権限が必要です。' };
    }

     if (user.id === userId) {
        return { error: "自身の管理者ステータスは変更できません。" };
    }

    const { error } = await supabase
        .from('members')
        .update({ is_admin: !currentStatus })
        .eq('supabase_auth_user_id', userId);

    if (error) {
        return { error: '管理者ステータスの更新に失敗しました。' };
    }

    revalidatePath('/dashboard/admin/members');
    return { error: null };
}

export async function deleteMember(userId: string) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { error: '認証が必要です。' };
    }

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) {
        return { error: '管理者権限が必要です。' };
    }

    if (user.id === userId) {
        return { error: "自分自身を削除することはできません。" };
    }

    const { error } = await supabase
        .from('members')
        .update({ deleted_at: new Date().toISOString() })
        .eq('supabase_auth_user_id', userId);

    if (error) {
        return { error: 'メンバーの削除に失敗しました。' };
    }

    revalidatePath('/dashboard/admin/members');
    return { error: null };
}

export async function updateMemberTeams(memberId: string, teamIds: string[]): Promise<{ error: string | null }> {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: '認証が必要です。' };

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) return { error: '管理者権限が必要です。' };

    try {
        const { error: deleteError } = await supabase
            .from('member_team_relations')
            .delete()
            .eq('member_id', memberId);

        if (deleteError) throw deleteError;

        if (teamIds.length > 0) {
            const newRelations = teamIds.map(teamId => ({
                member_id: memberId,
                team_id: teamId,
            }));
            const { error: insertError } = await supabase
                .from('member_team_relations')
                .insert(newRelations);

            if (insertError) throw insertError;
        }

        const { data: member } = await supabase.from('members').select('discord_uid').eq('supabase_auth_user_id', memberId).single();
        if (member) {
            await syncDiscordRoles(member.discord_uid);
        }

        revalidatePath('/dashboard/admin/members');
        revalidatePath('/dashboard/admin/teams');
        return { error: null };
    } catch (e: any) {
        console.error("Error updating member teams:", e);
        return { error: e.message };
    }
}


export async function syncAllDiscordRoles(): Promise<{ error: string | null, message: string }> {
    try {
        await checkAdmin();
        const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
        const token = process.env.STEM_BOT_API_BEARER_TOKEN;

        if (!apiUrl || !token) {
            throw new Error('API URL or Bearer Token is not configured for Discord role sync.');
        }

        const res = await fetch(`${apiUrl}/api/roles/sync-all`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            cache: 'no-store',
        });

        const result = await res.json();

        if (!res.ok || !result.success) {
            const errorMessage = result.error || `API returned status ${res.status}`;
            console.error('[Discord Bot] Failed to sync all roles.', errorMessage);
            throw new Error(errorMessage);
        }

        if (result.message === 'No members to sync') {
             return { error: null, message: '同期対象のメンバーが見つかりませんでした。' };
        }

        const successMessage = `${result.synced}人の同期に成功しました。`;
        const failureMessage = result.failed > 0 ? `${result.failed}人の同期に失敗しました。` : '';
        const totalMessage = `(合計: ${result.total}人)`;

        let finalMessage = `${successMessage} ${failureMessage} ${totalMessage}`.trim();
        if (result.errors && result.errors.length > 0) {
            console.error('[Discord Bot] Sync-all errors:', result.errors);
        }

        return { error: null, message: finalMessage };

    } catch (e: any) {
        return { error: e.message, message: '' };
    }
}

export async function updateStatusesForNewAcademicYear(highSchoolFirstYearGeneration: number): Promise<{ error: string | null, message: string }> {
    try {
        await checkAdmin();
        if (!highSchoolFirstYearGeneration || highSchoolFirstYearGeneration <= 0) {
            return { error: '有効な期数を指定してください。', message: '' };
        }

        const supabase = await createAdminClient();

        const highSchoolGenerations = [
            highSchoolFirstYearGeneration,      // 1st year
            highSchoolFirstYearGeneration - 1,  // 2nd year
            highSchoolFirstYearGeneration - 2   // 3rd year
        ];
        const juniorHighSchoolGenerations = [
            highSchoolFirstYearGeneration + 1,  // 3rd year
            highSchoolFirstYearGeneration + 2,  // 2nd year
            highSchoolFirstYearGeneration + 3   // 1st year
        ];

        const allStudentGenerations = [...highSchoolGenerations, ...juniorHighSchoolGenerations];

        console.log('[年度更新] 高校生の期:', highSchoolGenerations);
        console.log('[年度更新] 中学生の期:', juniorHighSchoolGenerations);
        console.log('[年度更新] 在籍中の期（全）:', allStudentGenerations);

        // Get count before update for better message
        const { count: totalMembers, error: countError } = await supabase
            .from('members')
            .select('*', { count: 'exact', head: true })
            .is('deleted_at', null);

        if (countError) throw new Error(`メンバー数の取得に失敗: ${countError.message}`);


        // Update High School Students
        const { error: hsError, data: hsData } = await supabase
            .from('members')
            .update({ status: 1 }) // 1: High School
            .in('generation', highSchoolGenerations)
            .is('deleted_at', null)
            .select();
        if (hsError) throw new Error(`高校生の更新に失敗: ${hsError.message}`);
        console.log(`[年度更新] 高校生に更新: ${hsData?.length || 0}人`);

        // Update Junior High School Students
        const { error: jhsError, data: jhsData } = await supabase
            .from('members')
            .update({ status: 0 }) // 0: Junior High
            .in('generation', juniorHighSchoolGenerations)
            .is('deleted_at', null)
            .select();
        if (jhsError) throw new Error(`中学生の更新に失敗: ${jhsError.message}`);
        console.log(`[年度更新] 中学生に更新: ${jhsData?.length || 0}人`);

        // Update OB/OG (期が在籍中リストに含まれないメンバー)
        const { error: obError, data: obData } = await supabase
            .from('members')
            .update({ status: 2 }) // 2: OB/OG
            .not('generation', 'in', `(${allStudentGenerations.join(',')})`)
            .is('deleted_at', null)
            .select();
        if (obError) {
            console.error('[年度更新] OB/OG更新エラー:', obError);
            throw new Error(`OB/OGの更新に失敗: ${obError.message}`);
        }
        console.log(`[年度更新] OB/OGに更新: ${obData?.length || 0}人`, obData);

        // Re-sync all members' roles
        await syncAllDiscordRoles();

        revalidatePath('/dashboard/admin/members');

        return { error: null, message: `全${totalMembers || 0}人のメンバーのステータスを更新し、ロールの同期を開始しました。` };

    } catch (e: any) {
        console.error("Failed to update for new academic year:", e);
        return { error: e.message, message: '' };
    }
}


export async function renameGraduatesToNewFormat(): Promise<{ error: string | null, message: string }> {
    try {
        await checkAdmin();
        const supabase = await createAdminClient();

        const { data: obMembers, error: fetchError } = await supabase
            .from('members')
            .select('supabase_auth_user_id, discord_uid')
            .eq('status', 2)
            .is('deleted_at', null)
            .not('discord_uid', 'is', null);

        if (fetchError) throw new Error(`OB/OGメンバーの取得に失敗: ${fetchError.message}`);
        if (!obMembers || obMembers.length === 0) {
            return { error: null, message: 'OB/OGメンバーが見つかりませんでした。' };
        }

        const { data: { users: allUsers }, error: usersError } = await supabase.auth.admin.listUsers({ page: 1, perPage: 1000 });
        if (usersError) throw new Error(`ユーザー情報の取得に失敗: ${usersError.message}`);

        const userMap = new Map(allUsers.map(u => [u.id, u]));

        let successCount = 0;
        let failCount = 0;

        for (const member of obMembers) {
            const user = userMap.get(member.supabase_auth_user_id);
            if (!user || !member.discord_uid) { failCount++; continue; }
            const fullName = ((user.user_metadata?.last_name ?? '') + (user.user_metadata?.first_name ?? '')).replace(/\s/g, '');
            if (!fullName) {
                failCount++;
                console.error(`[renameGraduates] Skipping ${member.discord_uid}: 本名(last_name/first_name)が取得できません。`);
                continue;
            }
            await syncDiscordNickname(member.discord_uid, fullName);
            successCount++;
        }

        return {
            error: null,
            message: `${successCount}人の卒業生のニックネームを「名前(第n期卒業生)」形式に更新しました。${failCount > 0 ? `（${failCount}人は名前情報なしのためスキップ）` : ''}`,
        };
    } catch (e: any) {
        console.error('Failed to rename graduates:', e);
        return { error: e.message, message: '' };
    }
}

